	/**
	 * Default Constructor
	 */
    public TagService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new TagEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(TagRepository.class) );
		this.validator		= applicationContext.getBean(TagValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Tag
	 */
		public Tag createTag( CreateTagCommand command ) {

		Tag entity = new Tag();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setTagId( command.getTagId() );
            entity.setName( command.getName() );
            entity.setCategory( command.getCategory() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Tag {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateTagCommand
	 * @return		Tag
	 */
	public Tag updateTag( UpdateTagCommand command ) {

		Tag entity = new Tag();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setTagId( command.getTagId() );
            entity.setName( command.getName() );
            entity.setDatasets( command.getDatasets() );
            entity.setModels( command.getModels() );
            entity.setModelVersions( command.getModelVersions() );
            entity.setDashboards( command.getDashboards() );
            entity.setReports( command.getReports() );
            entity.setFeatureSets( command.getFeatureSets() );
            entity.setMetrics( command.getMetrics() );
            entity.setCategory( command.getCategory() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Tag {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteTagCommand
	 */
	public void delete( DeleteTagCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getTagId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Tag {0} ", id );

	}

	/**
	 * Method to retrieve the Tag via TagFetchOneSummary
	 * @param 	summary TagFetchOneSummary
	 * @return 	TagFetchOneResponse
	 */
	public Tag getTag( TagFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "TagFetchOneSummary arg cannot be null" );

		Tag entity = null;
		UUID id = summary.getTagId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Tag using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Tags
	 *
	 * @return 	List<Tag>
	 */
    public List<Tag> getAllTag() {
		List<Tag> list = projector.findAll( new FindAllTagQuery() );
		return list;
	}


